def process(df):
    import pandas as pd, numpy as np
    np.random.seed(42)
    dates = pd.bdate_range(end='2026-07-22', periods=60)
    price = 10 * np.cumprod(1 + np.random.normal(0, 0.02, 60))
    full = pd.DataFrame({
        'code': '000001', 'dt': dates,
        'open': price, 'high': price*1.01, 'low': price*0.99, 'close': price,
        'vol': np.random.randint(500, 5000, 60).astype(float),
    })
    return full.drop([5, 15, 30]).reset_index(drop=True)
